// shelfUniqueKeys are the conflict targets of Shelf's unique keys, and
// the assignment an upsert that sets nothing writes, so the row it
// conflicts with is returned (sqlutil.UniqueKey, D79).
var shelfUniqueKeys = map[ShelfUniqueKey]struct{ conflict, keep string }{
	ShelfUniqueById: {`(id)`, `id = EXCLUDED.id`},
}

// UpsertOne inserts input, or, when a row already holds its value of the
// unique key on, applies update to that row instead, and returns the row
// (D79). The insert writes what CreateOne writes and the update what
// UpdateOne writes, updated_at and updated_by among it, but an update that
// sets no field leaves the row as it is. A soft-deleted row that holds the key is
// left as it is, and UpsertOne returns ErrNotFound.
func (r *ShelfRepository) UpsertOne(ctx context.Context, input *types.Shelf, on ShelfUniqueKey, update *ShelfUpdate) (*types.Shelf, error) {
	key, ok := shelfUniqueKeys[on]
	if !ok {
		return nil, fmt.Errorf("orm: Shelf has no unique key %q", string(on))
	}
	if update == nil {
		update = &ShelfUpdate{}
	}
	// Set audit fields
	if !HasUserID(ctx) {
		return nil, ErrNoUserInContext
	}
	input.CreatedBy = GetUserID(ctx)
	input.UpdatedBy = GetUserID(ctx)

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := shelfUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: label
	fields = append(fields, `label`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Label)
	// Required field: createdBy
	fields = append(fields, `created_by`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.CreatedBy.ToUUID())
	// Required field: updatedBy
	fields = append(fields, `updated_by`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.UpdatedBy.ToUUID())
	// Optional field: deletedAt - only add if set
	{
		if input.DeletedAt != nil {
			fields = append(fields, `deleted_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.DeletedAt))
		}
	}
	// Optional field: deletedBy - only add if set
	{
		if input.DeletedBy != nil {
			fields = append(fields, `deleted_by`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, input.DeletedBy.ToUUID())
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses []string
	if update.Label != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`label = $%d`, paramNum))
		values = append(values, *update.Label)
	}

	if len(setClauses) == 0 {
		// An update that sets no field leaves the row as it is, stamps and
		// all, and returns it.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
		values = append(values, time.Now())

		// Set updated_by
		if update.UpdatedBy != nil {
			paramNum++
			setClauses = append(setClauses, fmt.Sprintf("updated_by = $%d", paramNum))
			values = append(values, *update.UpdatedBy)
		} else if HasUserID(ctx) {
			paramNum++
			setClauses = append(setClauses, fmt.Sprintf("updated_by = $%d", paramNum))
			values = append(values, GetUserID(ctx))
		}

	}

	query := fmt.Sprintf(
		`INSERT INTO shelf (%s) VALUES (%s) ON CONFLICT %s DO UPDATE SET %s WHERE shelf.deleted_at IS NULL RETURNING "id", "label", "created_at", "created_by", "updated_at", "updated_by", "deleted_at", "deleted_by", "_version"`,
		strings.Join(fields, ", "),
		strings.Join(placeholders, ", "),
		key.conflict,
		strings.Join(setClauses, ", "),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.Shelf{}
	// Create temporary variables for nullable fields that need pointer scanning

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.Id,

		&result.Label,

		&result.CreatedAt,

		&result.CreatedBy,

		&result.UpdatedAt,

		&result.UpdatedBy,

		&result.DeletedAt,

		&result.DeletedBy,

		&result.Version,
	); err != nil {
		if err == pgx.ErrNoRows {
			// The row the key conflicts with is soft-deleted.
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	// Set relationship IDs from scanned FK values

	return result, nil
}

// CreateMany inserts multiple Shelf records in a single statement
func (r *ShelfRepository) CreateMany(ctx context.Context, inputs []*types.Shelf) ([]*types.Shelf, error) {
	if len(inputs) == 0 {
		return []*types.Shelf{}, nil
	}

	// Set audit fields
	if !HasUserID(ctx) {
		return nil, ErrNoUserInContext
	}
	for _, input := range inputs {
		input.CreatedBy = GetUserID(ctx)
	}
	for _, input := range inputs {
		input.UpdatedBy = GetUserID(ctx)
	}

	// Build the batch INSERT in one pass over the fields. Each row records every
	// candidate column in the same order, with the value it binds or no value
	// when it leaves an optional column unset; buildBatchInsert inserts the
	// columns any row sets and writes DEFAULT for a row that leaves one unset.
	batch := make([][]batchInsertCell, 0, len(inputs))
	for _, input := range inputs {
		var row []batchInsertCell
		// Primary key: id. Schema-owned identities may supply a stable
		// UUID, matching CreateOne; a row without one takes the generated default.
		{
			cell := batchInsertCell{column: `id`}
			var zeroPrimaryKey types.IdentityUUID
			if primaryKey, ok := shelfUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
				cell.value, cell.set = primaryKey.ToUUID(), true
			}
			row = append(row, cell)
		}
		// Required field: label
		{
			cell := batchInsertCell{column: `label`, set: true}
			cell.value = input.Label
			row = append(row, cell)
		}
		// Required field: createdBy
		{
			cell := batchInsertCell{column: `created_by`, set: true}
			cell.value = input.CreatedBy.ToUUID()
			row = append(row, cell)
		}
		// Required field: updatedBy
		{
			cell := batchInsertCell{column: `updated_by`, set: true}
			cell.value = input.UpdatedBy.ToUUID()
			row = append(row, cell)
		}
		// Optional field: deletedAt
		{
			cell := batchInsertCell{column: `deleted_at`}
			if input.DeletedAt != nil {
				cell.value = time.Time(*input.DeletedAt)
				cell.set = true
			}
			row = append(row, cell)
		}
		// Optional field: deletedBy
		{
			cell := batchInsertCell{column: `deleted_by`}
			if input.DeletedBy != nil {
				cell.value = input.DeletedBy.ToUUID()
				cell.set = true
			}
			row = append(row, cell)
		}

		// Relationship foreign key columns, matching CreateOne
		batch = append(batch, row)
	}
	fieldNames, valuePlaceholders, values := buildBatchInsert(batch)

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	returningClauseMany := `"id", "label", "created_at", "created_by", "updated_at", "updated_by", "deleted_at", "deleted_by", "_version"`
	query := fmt.Sprintf(
		`INSERT INTO shelf (%s) VALUES %s RETURNING %s`,
		strings.Join(fieldNames, ", "),
		strings.Join(valuePlaceholders, ", "),
		returningClauseMany,
	)

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute batch insert: %w", err)
	}
	defer rows.Close()

	// Scan results
	results := []*types.Shelf{}
	for rows.Next() {
		result := &types.Shelf{}
		// Create temporary variables for nullable fields that need pointer scanning

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&result.Id,

			&result.Label,

			&result.CreatedAt,

			&result.CreatedBy,

			&result.UpdatedAt,

			&result.UpdatedBy,

			&result.DeletedAt,

			&result.DeletedBy,

			&result.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}

		// Copy nullable fields when present

		// Set relationship IDs from scanned FK values
		results = append(results, result)
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}

	return results, nil
}

// UpdateOne updates a single Shelf record by ID
func (r *ShelfRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *ShelfUpdate) (*types.Shelf, error) {
	return r.updateOne(ctx, id, update, nil)
}

// UpdateOneIfVersion updates a single Shelf only if its current _version matches expectedVersion.
// It returns ErrVersionConflict when the row exists at another version and
// ErrNotFound when it does not exist.
func (r *ShelfRepository) UpdateOneIfVersion(ctx context.Context, id types.IdentityUUID, expectedVersion int64, update *ShelfUpdate) (*types.Shelf, error) {
	return r.updateOne(ctx, id, update, &expectedVersion)
}

// versionMiss tells apart why a write fenced on _version matched no row:
// ErrVersionConflict when the row exists at another version, ErrNotFound when
// it does not exist or is soft-deleted.
func (r *ShelfRepository) versionMiss(ctx context.Context, id types.IdentityUUID) error {
	query := `SELECT _version FROM shelf WHERE id = $1 AND deleted_at IS NULL`

	var version int64
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, id.ToUUID())
	} else {
		row = r.db.pool.QueryRow(ctx, query, id.ToUUID())
	}
	if err := row.Scan(&version); err != nil {
		if err == pgx.ErrNoRows {
			return ErrNotFound
		}
		return fmt.Errorf("failed to read Shelf version: %w", err)
	}
	return ErrVersionConflict
}

func (r *ShelfRepository) updateOne(ctx context.Context, id types.IdentityUUID, update *ShelfUpdate, expectedVersion *int64) (*types.Shelf, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Label != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`label = $%d`, paramNum))
		values = append(values, *update.Label)
	}

	// Set updated_at
	paramNum++
	setClauses = append(setClauses, fmt.Sprintf("updated_at = $%d", paramNum))
	values = append(values, time.Now())

	// Set updated_by
	if update.UpdatedBy != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("updated_by = $%d", paramNum))
		values = append(values, *update.UpdatedBy)
	} else if HasUserID(ctx) {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf("updated_by = $%d", paramNum))
		values = append(values, GetUserID(ctx))
	}

	if len(setClauses) == 0 {
		return nil, fmt.Errorf("no fields to update")
	}

	paramNum++
	values = append(values, id.ToUUID())

	query := fmt.Sprintf(
		`UPDATE shelf SET %s WHERE id = $%d`,
		strings.Join(setClauses, ", "),
		paramNum,
	)
	if expectedVersion != nil {
		paramNum++
		values = append(values, *expectedVersion)
		query += fmt.Sprintf(" AND _version = $%d", paramNum)
	}
	query += " AND deleted_at IS NULL"

	// Build RETURNING clause with explicit column order matching scan order (using OrderedMembers for schema order)
	query += ` RETURNING "id", "label", "created_at", "created_by", "updated_at", "updated_by", "deleted_at", "deleted_by", "_version"`

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}

	// Scan result
	result := &types.Shelf{}
	// Create temporary variables for nullable fields that need pointer scanning

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	if err := row.Scan(

		&result.Id,

		&result.Label,

		&result.CreatedAt,

		&result.CreatedBy,

		&result.UpdatedAt,

		&result.UpdatedBy,

		&result.DeletedAt,

		&result.DeletedBy,

		&result.Version,
	); err != nil {
		if err == pgx.ErrNoRows {
			if expectedVersion != nil {
				return nil, r.versionMiss(ctx, id)
			}
			return nil, ErrNotFound
		}
		return nil, fmt.Errorf("failed to scan result: %w", err)
	}

	// Copy nullable fields when present

	// Set relationship IDs from scanned FK values

	return result, nil
}

