// DeleteOne soft deletes a single Shelf record by ID
func (r *ShelfRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	if !HasUserID(ctx) {
		return ErrNoUserInContext
	}
	query := `UPDATE shelf SET deleted_at = $1, deleted_by = $2 WHERE id = $3 AND deleted_at IS NULL`
	queryArgs := []interface{}{time.Now(), GetUserID(ctx), id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}

