// DeleteMany soft deletes multiple Shelf records matching the filter
func (r *ShelfRepository) DeleteMany(ctx context.Context, filter *ShelfFilter) (int, error) {
	if !HasUserID(ctx) {
		return 0, ErrNoUserInContext
	}

	// Build WHERE clause
	values := []interface{}{time.Now(), GetUserID(ctx)}
	whereClause := filter.buildWhereClause(&values, 2)

	if whereClause == "" {
		whereClause = " WHERE deleted_at IS NULL"
	} else {
		whereClause += " AND deleted_at IS NULL"
	}
	query := fmt.Sprintf(`UPDATE shelf SET deleted_at = $1, deleted_by = $2%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// HardDeleteOne permanently deletes a single Shelf record by ID
func (r *ShelfRepository) HardDeleteOne(ctx context.Context, id types.IdentityUUID) error {
	query := `DELETE FROM shelf WHERE id = $1`
	queryArgs := []interface{}{id.ToUUID()}

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, queryArgs...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, queryArgs...)
	}
	if err != nil {
		return fmt.Errorf("failed to delete record: %w", err)
	}

	if result.RowsAffected() == 0 {
		return ErrNotFound
	}

	return nil
}
